create or replace function public.block_login_device(p_session_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public,auth as $$declare target_user uuid;target_hash text;begin if not public.is_live_auth_session()then raise exception 'Invalid session' using errcode='42501';end if;select user_id,device_key_hash into target_user,target_hash from public.login_devices where session_id=p_session_id;if target_user is null then raise exception 'Device not found';end if;if target_user<>auth.uid()and not public.is_dashboard_admin()then raise exception 'Not authorized' using errcode='42501';end if;update public.login_devices set status='blocked',blocked_at=now(),blocked_by=auth.uid()where user_id=target_user and device_key_hash=target_hash;delete from auth.sessions where id in(select session_id from public.login_devices where user_id=target_user and device_key_hash=target_hash);end$$;
create or replace function public.unblock_login_device(p_session_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public,auth as $$declare target_user uuid;target_hash text;begin if not public.is_live_auth_session()then raise exception 'Invalid session' using errcode='42501';end if;select user_id,device_key_hash into target_user,target_hash from public.login_devices where session_id=p_session_id;if target_user is null then raise exception 'Device not found';end if;if target_user<>auth.uid()and not public.is_dashboard_admin()then raise exception 'Not authorized' using errcode='42501';end if;update public.login_devices set status='active',blocked_at=null,blocked_by=null where user_id=target_user and device_key_hash=target_hash;end$$;
revoke all on function public.block_login_device(uuid),public.unblock_login_device(uuid) from public,anon;
grant execute on function public.block_login_device(uuid),public.unblock_login_device(uuid) to authenticated;
